#ifndef FMT_STATIC_THOUSANDS_SEPARATOR
template <typename Locale>
locale_ref::locale_ref(const Locale& loc) : locale_(&loc) {
  static_assert(std::is_same<Locale, std::locale>::value, "");
}

template <typename Locale> Locale locale_ref::get() const {
  static_assert(std::is_same<Locale, std::locale>::value, "");
  return locale_ ? *static_cast<const std::locale*>(locale_) : std::locale();
}

template <typename Char>
inline auto locale_numpunct(locale_ref loc) -> const std::numpunct<Char>& {
  return std::use_facet<std::numpunct<Char>>(
      locale_ref_materialize<std::locale>(loc));
}

template <typename Char>
inline auto thousands_sep_from_locale(const std::numpunct<Char>& facet)
    -> thousands_sep_result<Char> {
  auto grouping = facet.grouping();
  Char sep = Char();
  if (!grouping.empty()) sep = facet.thousands_sep();
  return {std::move(grouping), sep};
}

template <typename Char>
FMT_FUNC auto thousands_sep_impl(locale_ref loc) -> thousands_sep_result<Char> {
  return thousands_sep_from_locale(locale_numpunct<Char>(loc));
}
